// npm run eval:synth [-- <root>] — robustness check on simulator weeks (different network sizes,
// pressures, noise, repair times) generated by Hadent's ml/gen_data.py into data/synth/<week>/
// with labels.json. Scores the rules detector (never trained on anything) and, per pump failure,
// whether the planner finds a valid plan. Eval-only.
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { loadFolder } from '../../worker/src/folder';
import { analyze } from '../../core/src/analyze';
import { tsAt } from '../../core/src/telemetry';
import { parseAnswerKey } from './answerKey';
import { scoreDetection } from './detection';

const root = resolve(process.argv[2] ?? 'data/synth');
if (!existsSync(root)) {
  console.log(`no ${root}; generate with: python ml/gen_data.py --n 4 --out data/synth --seed 9001`);
  process.exit(1);
}
let hits = 0;
let total = 0;
let fa = 0;
for (const name of readdirSync(root).sort()) {
  const dir = join(root, name);
  const lp = join(dir, 'labels.json');
  if (!existsSync(lp) || !existsSync(join(dir, 'telemetry.csv'))) continue;
  const labels = parseAnswerKey(readFileSync(lp, 'utf8'));
  const d = loadFolder(dir);
  const t0 = Date.now();
  const s = scoreDetection(d.model, d.grid, labels, { tolSec: 3600, sweepStepSec: 0 });
  const ms = Date.now() - t0;
  if (!s.ok) {
    console.log(`${name}: ${s.error}`);
    continue;
  }
  const v = s.value;
  const cats = Object.entries(v.perCategory).map(([c, x]) => `${c} ${x.hits}/${x.total}`).join('  ');
  const h = v.matching.matches.filter((m) => m.detected).length;
  hits += h;
  total += v.matching.matches.length;
  fa += v.matching.falseAlarms.length;
  // plan every pump failure at its onset (smoke: planner runs and returns a valid plan quickly)
  let planned = 0;
  let planMs = 0;
  for (const l of labels.filter((x) => x.category === 'pump_failure')) {
    const tp = Date.now();
    const out = analyze({ model: d.model, grid: d.grid, asOfUnix: l.onsetUnix + d.grid.stepSec });
    planMs = Math.max(planMs, Date.now() - tp);
    if (out.plans.some((p) => p.facilities.some((f) => f.facilityId === l.facility))) planned++;
  }
  const nf = labels.filter((x) => x.category === 'pump_failure').length;
  console.log(
    `${name}: ${d.model.systems.length} systems, ${d.model.facilities.length} facilities, repair ${d.model.repairHoursPumpFailure} h · ${cats} · FA ${v.matching.falseAlarms.length} · detect ${ms} ms · planned ${planned}/${nf} (max analyze ${planMs} ms)`,
  );
  for (const m of v.matching.matches) if (!m.detected) console.log(`   miss ${m.label.id} ${m.label.category} ${m.label.asset} onset ${new Date(m.label.onsetUnix * 1000).toISOString().slice(5, 16)}`);
  for (const e of v.matching.falseAlarms) console.log(`   FA ${e.category} ${e.assetId} ${new Date(e.onsetUnix * 1000).toISOString().slice(5, 16)} → ${e.endUnix ? new Date(e.endUnix * 1000).toISOString().slice(5, 16) : 'ongoing'} conf ${e.confidence.toFixed(2)} (now ${new Date(tsAt(d.grid, d.grid.n - 1) * 1000).toISOString().slice(5, 16)})`);
}
console.log(`TOTAL rules detector: ${hits}/${total} labelled events, ${fa} false alarms`);
